(() => {
  const {money,escapeHtml:e,vehicleTitle,estimate} = DF;
  const root = document.querySelector('#vehicle-content');
  const id = new URLSearchParams(location.search).get('id');
  DFInventory.load().then(data => {
    const car = data.vehicles.find(item => String(item.id) === id);
    if (!car) {root.innerHTML = '<div class="page-message"><h1>Let’s find your next drive.</h1><p>This vehicle could not be found in the current collection.</p><a class="button button-black" href="index.html#showroom">Back to the showroom <span>↗</span></a></div>';return;}
    document.title = `${car.year} ${vehicleTitle(car)} | Driving Force`;
    const mileage = Number(car.mile).toLocaleString('en-ZA').replace(/,/g,' ')+' km';
    const description = Array.isArray(car.description) && car.description.length ? car.description : [`${car.year} ${vehicleTitle(car)}, ${car.variant}. ${car.colour} exterior, ${mileage}, ${car.fuelType.toLowerCase()} fuel and ${car.transmission.toLowerCase()} transmission. Contact our showroom for more information about this vehicle.`];
    const enquiry = 'mailto:info@drivingforce.biz?'+new URLSearchParams({subject:`Vehicle enquiry: ${car.year} ${vehicleTitle(car)} (${car.stock_code})`,body:`Hello Driving Force,\n\nI would like to enquire about the ${car.year} ${vehicleTitle(car)}, stock ${car.stock_code}. Please confirm availability and help me arrange a viewing.\n\nhttps://www.driving-force.co.za/vehicle.html?id=${car.id}`}).toString().replace(/\+/g,'%20');
    root.innerHTML = `<div class="vehicle-breadcrumb"><a class="back-link" href="index.html#showroom">← Back to the showroom</a><span>STOCK ${e(car.stock_code)}</span></div>
      <div class="vehicle-hero">
        <div class="vehicle-gallery"><button type="button" class="photo-open" aria-label="Enlarge photo of ${e(vehicleTitle(car))}" aria-haspopup="dialog"><img class="detail-photo" src="${e(car.localImage)}" alt="${e(car.year+' '+vehicleTitle(car)+' in '+car.colour)}" width="800" height="533" fetchpriority="high"><span class="photo-expand" aria-hidden="true">View full photo <span>↗</span></span></button><div class="photo-caption"><span>${e(car.colour)} exterior</span><span>Driving Force · Cape Town</span></div></div>
        <section class="vehicle-summary" aria-labelledby="vehicle-title"><p class="detail-eyebrow"><span class="red-line" aria-hidden="true"></span>${car.year} / ${e(car.body_type)}</p><h1 id="vehicle-title">${e(vehicleTitle(car))}</h1><p class="detail-variant">${e(car.variant)}</p><div class="vehicle-offer"><span class="detail-label">Asking price</span><strong class="detail-price">${money(car.value)}</strong></div><dl class="vehicle-key-facts">${[['Mileage',mileage],['Transmission',car.transmission],['Fuel type',car.fuelType]].map(([label,value])=>`<div><dt>${label}</dt><dd>${e(value)}</dd></div>`).join('')}</dl><a class="button button-red full-width vehicle-enquire" href="${e(enquiry)}">Email an enquiry <span aria-hidden="true">↗</span></a><a class="button button-outline full-width" href="visit.html?vehicle=${car.id}">Visit the showroom <span aria-hidden="true">↗</span></a><a class="detail-call" href="tel:+27212038888">Or call 021 203 8888</a><a class="finance-jump" href="#vehicle-finance">Explore finance options <span aria-hidden="true">↓</span></a></section>
      </div>
      <nav class="vehicle-section-links" aria-label="Vehicle information"><a href="#vehicle-overview">Overview</a><a href="#vehicle-specifications">Specifications</a>${car.features?.length?'<a href="#vehicle-equipment">Equipment</a>':''}<a href="#vehicle-finance">Finance</a></nav>
      <div class="vehicle-detail-body"><article class="vehicle-story"><section id="vehicle-overview" class="vehicle-section"><p class="detail-eyebrow">THE DETAILS</p><h2>About this vehicle.</h2><div class="vehicle-description">${description.map(p=>`<p>${e(p)}</p>`).join('')}</div></section>
        <section id="vehicle-specifications" class="vehicle-section"><h2>At a glance.</h2><dl class="detail-specs">${[['Year',car.year],['Mileage',mileage],['Transmission',car.transmission],['Fuel type',car.fuelType],['Colour',car.colour],['Body type',car.body_type],['Variant',car.variant],['Stock reference',car.stock_code]].map(([label,value])=>`<div><dt>${label}</dt><dd>${e(value)}</dd></div>`).join('')}</dl></section>
        ${car.features?.length?`<section id="vehicle-equipment" class="vehicle-section"><h2>Equipment highlights.</h2><ul class="vehicle-equipment">${car.features.map(feature=>`<li><span aria-hidden="true">✓</span>${e(feature)}</li>`).join('')}</ul><p class="stock-note">Equipment recorded in Driving Force’s original listing. Please confirm current fitment with the showroom.</p></section>`:''}
        <p class="stock-note">Inventory recorded ${e(data.retrieved)}. Please confirm current mileage, price and availability with our team.</p></article>
        <section id="vehicle-finance" class="vehicle-finance" aria-labelledby="estimate-title"><p class="detail-eyebrow">PLAN YOUR NEXT DRIVE</p><h2 id="estimate-title">Make it yours.</h2><p class="form-intro">Adjust the figures to explore a monthly payment.</p><form id="vehicle-estimate" class="estimate-form"><div class="form-grid"><label>Vehicle price<div class="line-input"><span>R</span><input name="price" type="number" readonly value="${car.value}" min="1" max="10000000" step="any" required inputmode="decimal"></div></label><label>Deposit<div class="line-input"><span>R</span><input name="deposit" type="number" value="0" min="0" step="any" required inputmode="decimal"></div></label><label>Net trade-in value<div class="line-input"><span>R</span><input name="tradeIn" type="number" value="0" min="0" step="any" required inputmode="decimal"></div></label><label>Annual interest rate<div class="line-input"><input name="rate" type="number" value="12" min="0" max="30" step="any" required inputmode="decimal"><span>%</span></div></label><label class="span-two">Repayment term<select name="term">${[6,12,18,24,30,36,42,48,54,60,66,72,78,84,90,96].map(term=>`<option value="${term}" ${term===72?'selected':''}>${term} months</option>`).join('')}</select></label></div><p id="estimate-error" class="form-error" role="status"></p><div class="estimate-result" aria-live="polite"><span>Estimated monthly payment</span><p><strong id="estimate-monthly">—</strong><span> / month</span></p></div><a class="button button-red full-width" href="finance.html?vehicle=${car.id}" id="apply-finance">Apply for finance <span>↗</span></a><dl class="estimate-totals"><div><dt>Amount financed</dt><dd id="estimate-principal">—</dd></div><div><dt>Total interest</dt><dd id="estimate-interest">—</dd></div><div><dt>Total loan repayments</dt><dd id="estimate-total">—</dd></div></dl><p class="estimate-note">Illustrative estimate, subject to lender approval. Excludes fees, insurance and balloon payments. Net trade-in value is the amount available after settling any existing vehicle loan.</p><p class="estimate-note">Complete the full application here on our website.</p></form></section></div>
      <div class="vehicle-visit"><div><p class="detail-eyebrow">SEE IT. WANT IT. DRIVE IT.</p><h2>See it for yourself.</h2><p>21 Montague Drive, Montague Gardens, Cape Town.</p></div><div class="vehicle-visit-actions"><a class="button button-black" href="visit.html?vehicle=${car.id}">Plan your visit <span aria-hidden="true">↗</span></a><a class="phone-link" href="tel:+27212038888">Call 021 203 8888</a></div></div>
      <dialog class="vehicle-photo-dialog" aria-label="${e(vehicleTitle(car))} photo"><div class="photo-dialog-top"><span>${car.year} ${e(vehicleTitle(car))}</span><button type="button" class="photo-close" aria-label="Close photo">Close <span aria-hidden="true">×</span></button></div><img src="${e(car.localImage)}" alt="${e(car.year+' '+vehicleTitle(car)+' in '+car.colour)}" width="800" height="533"><p>Stock ${e(car.stock_code)} · ${e(car.colour)} exterior</p></dialog>`;
    const photoDialog = document.querySelector('.vehicle-photo-dialog');
    const photoOpen = document.querySelector('.photo-open');
    photoOpen.addEventListener('click',()=>photoDialog.showModal());
    document.querySelector('.photo-close').addEventListener('click',()=>photoDialog.close());
    photoDialog.addEventListener('click',event=>{if(event.target===photoDialog){const r=photoDialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)photoDialog.close();}});
    photoDialog.addEventListener('close',()=>photoOpen.focus({preventScroll:true}));
    const form = document.querySelector('#vehicle-estimate');
    form.addEventListener('submit',event=>event.preventDefault());
    function calculate() {
      const values = Object.fromEntries([...new FormData(form)].map(([name,value])=>[name,value === '' ? NaN : Number(value)]));
      const result = form.checkValidity() ? estimate(values) : null;
      document.querySelector('#estimate-error').textContent = result ? '' : 'Enter valid amounts. Deposit and net trade-in together cannot exceed the vehicle price.';
      for(const key of ['monthly','principal','interest','total']) document.querySelector('#estimate-'+key).textContent = result ? money(result[key]) : '—';
      // Only non-personal vehicle and estimate values are passed to the application.
      const params = new URLSearchParams({vehicle:car.id});
      if(result) for(const key of ['deposit','tradeIn','rate','term']) params.set(key,values[key]);
      document.querySelector('#apply-finance').href = 'finance.html?'+params;
    }
    form.addEventListener('input',calculate);calculate();
  }).catch(()=>{root.innerHTML='<div class="page-message"><h1>The vehicle could not load.</h1><p>Please try again or contact our showroom.</p><a class="button button-black" href="index.html#showroom">Back to the showroom</a></div>';});
})();
